import {usdt,at} from './crypto-format.js';
import {krwAmount,krwBasis,validKrwRate} from './crypto-krw.js';
import {configuredSeries} from './stock-chart-analysis.js';
import {newIndicator} from './stock-chart-state.js';
// Same Lightweight Charts renderer and closing-price indicator calculations as stock charts.
export function mountBinanceChart(root){
 let lib,chart,price,volume,lines=[],bars=[],data,id,days=365,kind='candles',oscillator='',averages=true,bands=false,ema=false,dead=false,version=0,abort,dialog,placeholder,inspectDate=null,pendingCandle,conversion;
 const money=v=>krwAmount(v,conversion);
 const ranges=[[7,'1주'],[30,'1개월'],[90,'3개월'],[365,'1년'],[0,'전체']];
 root.innerHTML=`<div class="crypto-chart-tools" role="group" aria-label="일봉 조회 기간">${ranges.map(([d,n])=>`<button data-days="${d}" aria-pressed="${d===days}">${n}</button>`).join('')}<select aria-label="차트 종류" class="crypto-chart-kind"><option value="candles">캔들</option><option value="line">선</option></select><button data-chart-full>전체 화면</button></div><details class="crypto-indicator-menu"><summary>지표</summary><label><input type="checkbox" data-ind="sma" checked> SMA 20·60</label><label><input type="checkbox" data-ind="ema"> EMA 12·26</label><label><input type="checkbox" data-ind="bb"> 볼린저밴드 20·2</label><select aria-label="보조지표" class="crypto-oscillator"><option value="">보조지표 없음</option><option value="rsi">RSI 14</option><option value="macd">MACD 12·26·9</option></select></details><small class="crypto-chart-range"></small><div class="crypto-chart-readout" aria-live="off"></div><div class="crypto-chart-plot"></div><div class="crypto-chart-state" role="status"></div><small class="crypto-chart-source"></small>`;
 const $=s=>root.querySelector(s),plot=$('.crypto-chart-plot'),state=$('.crypto-chart-state'),source=$('.crypto-chart-source');
 const indicators=()=>[...(averages?[newIndicator('sma',20),{...newIndicator('sma',60),colors:['#7562c7']}]:[]),...(ema?[newIndicator('ema',12),{...newIndicator('ema',26),colors:['#087f73']}]:[]),...(bands?[newIndicator('bb')]:[]),...(oscillator?[newIndicator(oscillator)]:[])];
 function remember(){if(!id)return;try{localStorage.setItem('moa.binance.chart:'+id,JSON.stringify({days,kind,averages,ema,bands,oscillator}));}catch{}}
 function restore(){let s;try{s=JSON.parse(localStorage.getItem('moa.binance.chart:'+id)||'null');}catch{}if(!s)return;days=ranges.some(([d])=>d===s.days)?s.days:365;kind=s.kind==='line'?'line':'candles';averages=s.averages!==false;ema=s.ema===true;bands=s.bands===true;oscillator=['rsi','macd'].includes(s.oscillator)?s.oscillator:'';$('[data-ind="sma"]').checked=averages;$('[data-ind="ema"]').checked=ema;$('[data-ind="bb"]').checked=bands;$('.crypto-oscillator').value=oscillator;$('.crypto-chart-kind').value=kind;root.querySelectorAll('[data-days]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.days)===days)));}
 function show(time){const i=Math.max(0,bars.findIndex(b=>b.date===time)),b=bars[i];if(!b)return;const values=configuredSeries(bars,indicators()).filter(s=>Number.isFinite(s.values[i]));$('.crypto-chart-readout').textContent=`${b.date} UTC · 원화 · 시 ${money(b.open)} · 고 ${money(b.high)} · 저 ${money(b.low)} · 종 ${money(b.close)} · 거래량 ${usdt(b.volume,true)}${values.length?' · '+values.map(s=>s.label+' '+(s.panel==='rsi'?usdt(s.values[i]):money(s.values[i]))).join(' · '):''}`;}
 function meta(){if(!data)return;source.textContent=[data.source,'KRW 환산',krwBasis(conversion),'전 구간 동일 환산율 · 등락률은 USDT 기준',data.dataAsOf?'데이터 기준 '+at(data.dataAsOf):null,'수신 '+at(data.receivedAt),data.stale?'갱신 지연':null,data.message].filter(Boolean).join(' · ');$('.crypto-chart-range').textContent=data.available?`${data.available.first} ~ ${data.available.last} · ${bars.length}개 일봉 · 지표 계산용 이전 구간 포함`:'';}
 function resetView(){if(!chart||!bars.length)return;const end=bars.at(-1).time,from=days?bars.findIndex(b=>b.time>=end-(days-1)*86400):0;chart.timeScale().setVisibleLogicalRange({from:Math.max(-.5,from-.5),to:bars.length+.5});}
 function draw(){if(!lib||!bars.length||dead)return;if(!validKrwRate(conversion)){chart?.remove();chart=null;plot.hidden=true;state.hidden=false;state.textContent='원화 환산율 연결 필요 · 일봉 데이터는 보관됩니다.';return;}state.hidden=true;plot.hidden=false;const range=chart?.timeScale().getVisibleLogicalRange();chart?.remove();lines=[];plot.style.height=(oscillator?530:390)+'px';chart=lib.createChart(plot,{autoSize:true,layout:{background:{type:'solid',color:'#fff'},textColor:'#677587',fontFamily:'Pretendard, sans-serif',fontSize:11,panes:{separatorColor:'#E5EAF0',enableResize:true}},grid:{vertLines:{visible:false},horzLines:{color:'#f0f3f7'}},rightPriceScale:{borderVisible:false,alignLabels:true,minimumWidth:72},timeScale:{borderColor:'#E5EAF0',timeVisible:false,minBarSpacing:.1},localization:{locale:'ko-KR'},crosshair:{mode:lib.CrosshairMode.Normal},handleScroll:{mouseWheel:false,pressedMouseMove:true,horzTouchDrag:true,vertTouchDrag:false},handleScale:{mouseWheel:true,pinch:true,axisPressedMouseMove:{time:true,price:true}}});
 price=chart.addSeries(kind==='candles'?lib.CandlestickSeries:lib.LineSeries,{color:'#087f73',upColor:'#dc5360',downColor:'#377fce',wickUpColor:'#dc5360',wickDownColor:'#377fce',borderVisible:false,priceFormat:{type:'custom',minMove:1e-8,formatter:money},priceLineVisible:true});price.setData(bars.map(b=>kind==='candles'?{time:b.date,open:b.open,high:b.high,low:b.low,close:b.close}:{time:b.date,value:b.close}));
 volume=chart.addSeries(lib.HistogramSeries,{priceFormat:{type:'volume'},priceLineVisible:false,lastValueVisible:false},1);volume.setData(bars.map(b=>({time:b.date,value:b.volume,color:b.close>=b.open?'#dc536080':'#377fce80'})));chart.panes()[1].setHeight(90);
 for(const s of configuredSeries(bars,indicators())){const pane=s.panel==='price'?0:2;const series=chart.addSeries(s.panel==='histogram'?lib.HistogramSeries:lib.LineSeries,{color:s.color,lineWidth:2,priceFormat:{type:'custom',minMove:1e-8,formatter:s.panel==='rsi'?v=>usdt(v):money},lastValueVisible:false,priceLineVisible:false,autoscaleInfoProvider:s.panel==='rsi'?()=>({priceRange:{minValue:0,maxValue:100}}):undefined},pane);series.setData(bars.map((b,i)=>Number.isFinite(s.values[i])?{time:b.date,value:s.values[i],...(s.panel==='histogram'?{color:s.values[i]>=0?'#dc5360':'#377fce'}:{})}:{time:b.date}));lines.push({series,panel:s.panel});if(s.panel==='rsi')for(const p of [30,70])series.createPriceLine({price:p,color:'#9aa6b5',lineStyle:2,axisLabelVisible:true});if(s.panel==='macd'&&!lines.some(l=>l.zero)){series.createPriceLine({price:0,color:'#9aa6b5',lineStyle:2,axisLabelVisible:true});lines.at(-1).zero=true;}}
 if(oscillator)chart.panes()[2].setHeight(125);chart.subscribeCrosshairMove(e=>{inspectDate=typeof e.time==='string'?e.time:null;show(inspectDate||bars.at(-1)?.date);});if(range)chart.timeScale().setVisibleLogicalRange(range);else resetView();show(bars.at(-1).date);}
 async function load(){if(!id)return;const mine=++version;abort?.abort();abort=new AbortController();chart?.remove();chart=null;bars=[];$('.crypto-chart-readout').textContent='';$('.crypto-chart-range').textContent='';source.textContent='';state.hidden=false;state.textContent='Binance 일봉을 불러오고 있어요';plot.hidden=true;try{const response=await fetch('/api/crypto/chart?'+new URLSearchParams({id,days}),{signal:abort.signal});const next=await response.json();if(dead||mine!==version)return;if(!response.ok)throw new Error(next.message||'조회 실패');data=next;bars=next.points||[];meta();if(!bars.length){state.textContent='이 거래쌍의 과거 일봉 데이터가 없습니다.';return;}lib??=await import('/vendor/lightweight-charts/lightweight-charts.mjs');if(dead||mine!==version)return;state.hidden=true;plot.hidden=false;draw();if(pendingCandle){const p=pendingCandle;pendingCandle=null;update(p);}}catch(e){if(dead||mine!==version||e.name==='AbortError')return;state.textContent='차트 조회 실패 · '+e.message;}}
 function update(message){if(message.id!==id)return;if(!chart||!bars.length){pendingCandle=message;return;}const b=message.bar,last=bars.at(-1);if(b.date<last.date)return;if(b.date===last.date)bars[bars.length-1]=b;else bars.push(b);price.update(kind==='candles'?{time:b.date,open:b.open,high:b.high,low:b.low,close:b.close}:{time:b.date,value:b.close});volume.update({time:b.date,value:b.volume,color:b.close>=b.open?'#dc536080':'#377fce80'});const calculated=configuredSeries(bars,indicators());lines.forEach((l,i)=>{const value=calculated[i]?.values.at(-1);if(Number.isFinite(value))l.series.update({time:b.date,value,...(l.panel==='histogram'?{color:value>=0?'#dc5360':'#377fce'}:{})});});data.receivedAt=message.receivedAt;data.dataAsOf=message.receivedAt;data.stale=false;meta();show(inspectDate||b.date);}
 function closeFull(){if(!dialog)return;placeholder.replaceWith(root);dialog.close();dialog.remove();dialog=null;root.classList.remove('crypto-chart-full');$('[data-chart-full]').textContent='전체 화면';}
 function fullscreen(){if(dialog){closeFull();return;}placeholder=document.createComment('crypto-chart');root.replaceWith(placeholder);dialog=document.createElement('dialog');dialog.className='crypto-chart-dialog';document.body.append(dialog);dialog.append(root);root.classList.add('crypto-chart-full');dialog.addEventListener('cancel',e=>{e.preventDefault();closeFull();});dialog.showModal();$('[data-chart-full]').textContent='닫기 ✕';}
 const click=e=>{const b=e.target.closest('button');if(b?.hasAttribute('data-chart-full'))fullscreen();if(b?.dataset.days!==undefined){days=Number(b.dataset.days);root.querySelectorAll('[data-days]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));remember();load();}};root.addEventListener('click',click);
 const change=e=>{if(e.target.matches('.crypto-chart-kind'))kind=e.target.value;if(e.target.matches('.crypto-oscillator'))oscillator=e.target.value;if(e.target.dataset.ind==='sma')averages=e.target.checked;if(e.target.dataset.ind==='ema')ema=e.target.checked;if(e.target.dataset.ind==='bb')bands=e.target.checked;remember();draw();};root.addEventListener('change',change);
 return {setConversion(next){const changed=conversion?.rate!==next?.rate;conversion=next;meta();if(changed&&bars.length){draw();if(pendingCandle&&chart){const p=pendingCandle;pendingCandle=null;update(p);}}},select(next){if(next===id)return;id=next;pendingCandle=null;inspectDate=null;restore();load();},update,reload:load,destroy(){dead=true;++version;abort?.abort();chart?.remove();closeFull();root.removeEventListener('click',click);root.removeEventListener('change',change);}};
}
